CREATE TABLE notification_channel_settings(subject text NOT NULL,channel text NOT NULL CHECK(channel IN ('EMAIL','SMS','PUSH')),enabled boolean NOT NULL DEFAULT false,mode text NOT NULL,destination text NOT NULL DEFAULT '',subscription jsonb NOT NULL DEFAULT '{}',version bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(subject,channel));
CREATE UNIQUE INDEX channel_push_endpoint ON notification_channel_settings(destination) WHERE channel='PUSH' AND enabled;
CREATE TABLE notification_deliveries(id uuid PRIMARY KEY,notification_id uuid NOT NULL REFERENCES notifications,subject text NOT NULL,channel text NOT NULL,mode text NOT NULL,destination text NOT NULL,subscription jsonb NOT NULL,setting_version bigint NOT NULL,state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','RETRY','SENDING','ACCEPTED','DELIVERED','FAILED','UNKNOWN','CANCELLED')),attempts int NOT NULL DEFAULT 0,provider_id text,lease_token uuid,lease_until timestamptz NOT NULL DEFAULT '-infinity',next_attempt timestamptz NOT NULL DEFAULT now(),last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),displayed_at timestamptz,UNIQUE(notification_id,channel));
CREATE INDEX channel_delivery_due ON notification_deliveries(next_attempt,lease_until) WHERE state IN ('QUEUED','RETRY','SENDING','ACCEPTED');
CREATE INDEX channel_delivery_owner ON notification_deliveries(subject,created_at DESC);
